// Reports the ten most frequent words in a UTF-8 text file.
// A word is a maximal run of ASCII letters and digits; every other byte separates words.

const TOP = 10;

function isWordByte(b: number): boolean {
  return (b >= 0x30 && b <= 0x39) || // 0-9
    (b >= 0x41 && b <= 0x5a) || // A-Z
    (b >= 0x61 && b <= 0x7a); // a-z
}

function toLowerByte(b: number): number {
  return b >= 0x41 && b <= 0x5a ? b + 0x20 : b;
}

function countWords(bytes: Uint8Array): Map<string, number> {
  const counts = new Map<string, number>();
  let word: number[] = [];

  const flush = () => {
    if (word.length === 0) return;
    const key = String.fromCharCode(...word);
    counts.set(key, (counts.get(key) ?? 0) + 1);
    word = [];
  };

  for (const b of bytes) {
    if (isWordByte(b)) {
      word.push(toLowerByte(b));
    } else {
      flush();
    }
  }
  flush();

  return counts;
}

// Words are pure ASCII, so comparing JS strings code unit by code unit
// is the same as comparing their bytes.
function compareWords(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

async function main(): Promise<void> {
  const path = Deno.args[0];
  if (path === undefined) {
    console.error("usage: deno run main.ts <file>");
    Deno.exit(2);
  }

  const bytes = await Deno.readFile(path);
  const counts = countWords(bytes);

  const ranked = [...counts.entries()]
    .sort(([wa, ca], [wb, cb]) => cb - ca || compareWords(wa, wb))
    .slice(0, TOP);

  const out = ranked.map(([word, count]) => `${word} ${count}\n`).join("");
  if (out.length > 0) {
    await Deno.stdout.write(new TextEncoder().encode(out));
  }
}

await main();

