function countWords(bytes: Uint8Array): Map<string, number> {
  const counts = new Map<string, number>();
  const decoder = new TextDecoder();
  let start = -1;

  const flush = (end: number) => {
    if (start < 0) return;
    // Word bytes are ASCII, so toLowerCase only touches A-Z.
    const key = decoder.decode(bytes.subarray(start, end)).toLowerCase();
    counts.set(key, (counts.get(key) ?? 0) + 1);
    start = -1;
  };

  for (let i = 0; i < bytes.length; i++) {
    if (isWordByte(bytes[i])) {
      if (start < 0) start = i;
    } else {
      flush(i);
    }
  }
  flush(bytes.length);

  return counts;
}

